# Surah Al-Ahzab (chapter 33) — part 3: ayat 21-30 (IDs 3554-3563)
SURAH = 33

ENTRIES = {
3554: (
"بے شک تمہارے لیے رسول اللہ میں بہترین نمونہ ہے — جس کے لیے جو اللہ اور آخرت کے دن کی امید رکھتا ہے اور اللہ کو بہت یاد کرتا ہے",
"""۱۔ اسوۂ حسنہ — اللہ کی امید؛ آخرت؛ ذکرِ الٰہی۔
۲۔ ’’لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَۃٌ حَسَنَۃٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا‘‘ — بے شک تمہارے لیے رسول اللہ میں بہترین نمونہ ہے — جس کے لیے جو اللہ اور آخرت کے دن کی امید رکھتا ہے اور اللہ کو بہت یاد کرتا ہے — یعنی بے شک تمہارے لیے رسول اللہ میں بہترین نمونہ ہے جس کے لیے جو اللہ اور آخرت کے دن کی امید رکھتا ہے اور اللہ کو بہت یاد کرتا ہے۔
۳۔ عملی سبق: نبی ﷺ کی سنت پر عمل کرو؛ ذکرِ الٰہی کرو؛ اللہ سے ڈرو۔"""
),
3555: (
"اور جب مومنوں نے لشکر دیکھے تو کہا یہ وہی ہے جس کا اللہ اور اس کے رسول نے ہم سے وعدہ کیا تھا — اور اللہ اور اس کے رسول نے سچ کہا — اور انہیں ایمان اور سپردگی کے سوا کچھ نہ بڑھا",
"""۱۔ غزوۂ احزاب — مومنوں کا یقین؛ ایمان میں اضافہ؛ تسلیم و رضا۔
۲۔ ’’وَلَمَّا رَأَى الْمُؤْمِنُونَ الْأَحْزَابَ قَالُوا هَٰذَا مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ وَصَدَقَ اللَّهُ وَرَسُولُهُ وَمَا زَادَهُمْ إِلَّا إِيمَانًا وَتَسْلِيمًا‘‘ — اور جب مومنوں نے لشکر دیکھے تو کہا یہ وہی ہے جس کا اللہ اور اس کے رسول نے ہم سے وعدہ کیا تھا — اور اللہ اور اس کے رسول نے سچ کہا — اور انہیں ایمان اور سپردگی کے سوا کچھ نہ بڑھا — یعنی اور جب مومنوں نے لشکر دیکھے تو کہا یہ وہی ہے جس کا اللہ اور اس کے رسول نے ہم سے وعدہ کیا تھا اور اللہ اور اس کے رسول نے سچ کہا اور انہیں ایمان اور سپردگی کے سوا کچھ نہ بڑھا۔
۳۔ عملی سبق: آزمائش میں ایمان رکھو؛ اللہ کی رضا مانو؛ کچھ مت گھبراؤ۔"""
),
3556: (
"مومنوں میں سے کچھ لوگ ہیں جنہوں نے اللہ سے جو عہد کیا تھا اسے سچ کر دکھایا — ان میں سے بعض نے اپنی نذر پوری کر لی — اور بعض منتظر ہیں — اور انہوں نے کسی طرح کا تبدیلی نہیں کی",
"""۱۔ مومن — عہد کی سچائی؛ شہادت یا انتظار؛ عدمِ تبدیلی۔
۲۔ ’’مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا‘‘ — مومنوں میں سے کچھ لوگ ہیں جنہوں نے اللہ سے جو عہد کیا تھا اسے سچ کر دکھایا — ان میں سے بعض نے اپنی نذر پوری کر لی — اور بعض منتظر ہیں — اور انہوں نے کسی طرح کا تبدیلی نہیں کی — یعنی مومنوں میں سے کچھ لوگ ہیں جنہوں نے اللہ سے جو عہد کیا تھا اسے سچ کر دکھایا ان میں سے بعض نے اپنی نذر پوری کر لی اور بعض منتظر ہیں اور انہوں نے کسی طرح کا تبدیلی نہیں کی۔
۳۔ عملی سبق: عہد پر قائم رہو؛ اللہ کی راہ میں جان کی آزادی رکھو؛ ثابت قدم رہو۔"""
),
3557: (
"تاکہ اللہ سچوں کو ان کے سچ کا بدلہ دے — اور منافقوں کو چاہے تو عذاب دے یا ان کی توبہ قبول کرے — بے شک اللہ غفور و رحیم ہے",
"""۱۔ قیامت — سچوں کو بدلہ؛ منافقوں کا عذاب یا توبہ؛ غفور و رحیم۔
۲۔ ’’لِّيَجْزِيَ اللَّهُ الصَّادِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ الْمُنَافِقِينَ إِن شَاءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا‘‘ — تاکہ اللہ سچوں کو ان کے سچ کا بدلہ دے — اور منافقوں کو چاہے تو عذاب دے یا ان کی توبہ قبول کرے — بے شک اللہ غفور و رحیم ہے — یعنی تاکہ اللہ سچوں کو ان کے سچ کا بدلہ دے اور منافقوں کو چاہے تو عذاب دے یا ان کی توبہ قبول کرے بے شک اللہ غفور و رحیم ہے۔
۳۔ عملی سبق: سچے بنو؛ منافقت سے بچو؛ اللہ کی مغفرت مانگو۔"""
),
3558: (
"اور اللہ نے کافروں کو ان کے غصے میں واپس لوٹا دیا — انہوں نے کوئی خیر نہ پائی — اور اللہ نے مومنوں کے لیے جنگ کافی کر دی — اور اللہ قوی و عزیز ہے",
"""۱۔ غزوۂ احزاب کا نتیجہ — کافر خیر نہ پا سکے؛ اللہ کی مدد؛ قوی و عزیز۔
۲۔ ’’وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا‘‘ — اور اللہ نے کافروں کو ان کے غصے میں واپس لوٹا دیا — انہوں نے کوئی خیر نہ پائی — اور اللہ نے مومنوں کے لیے جنگ کافی کر دی — اور اللہ قوی و عزیز ہے — یعنی اور اللہ نے کافروں کو ان کے غصے میں واپس لوٹا دیا انہوں نے کوئی خیر نہ پائی اور اللہ نے مومنوں کے لیے جنگ کافی کر دی اور اللہ قوی و عزیز ہے۔
۳۔ عملی سبق: اللہ کی مدد پر بھروسہ رکھو؛ دشمنوں کا انجام دیکھو؛ اس سے ڈرو۔"""
),
3559: (
"اور جنہوں نے ان کی مدد کی اہلِ کتاب میں سے انہیں ان کے گڑھوں سے نیچے اتار دیا — اور ان کے دلوں میں خوف ڈال دیا — تم ان میں سے بعض کو قتل کرتے ہو اور بعض کو قید کرتے ہو",
"""۱۔ بنو قریظہ — قلعوں سے نزول؛ خوف؛ قتل و قید۔
۲۔ ’’وَأَنزَلَ الَّذِينَ ظَاهَرُوهُم مِّنْ أَهْلِ الْكِتَابِ مِن صَيَاصِيهِمْ وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا‘‘ — اور جنہوں نے ان کی مدد کی اہلِ کتاب میں سے انہیں ان کے گڑھوں سے نیچے اتار دیا — اور ان کے دلوں میں خوف ڈال دیا — تم ان میں سے بعض کو قتل کرتے ہو اور بعض کو قید کرتے ہو — یعنی اور جنہوں نے ان کی مدد کی اہلِ کتاب میں سے انہیں ان کے گڑھوں سے نیچے اتار دیا اور ان کے دلوں میں خوف ڈال دیا تم ان میں سے بعض کو قتل کرتے ہو اور بعض کو قید کرتے ہو۔
۳۔ عملی سبق: اللہ کی تائید دیکھو؛ دشمنوں کا انجام دیکھو؛ ایمان لاؤ۔"""
),
3560: (
"اور تمہیں ان کی زمین، ان کے گھر اور ان کے مال کا وارث بنا دیا — اور ایسی زمین کا بھی جس پر تم نے قدم نہیں رکھا — اور اللہ ہر چیز پر قادر ہے",
"""۱۔ غزوۂ بنی قریظہ — وراثت کی زمینیں؛ مال؛ اللہ کی قدرت۔
۲۔ ’’وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَارَهُمْ وَأَمْوَالَهُمْ وَأَرْضًا لَّمْ تَطَئُوهَا وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرًا‘‘ — اور تمہیں ان کی زمین، ان کے گھر اور ان کے مال کا وارث بنا دیا — اور ایسی زمین کا بھی جس پر تم نے قدم نہیں رکھا — اور اللہ ہر چیز پر قادر ہے — یعنی اور تمہیں ان کی زمین ان کے گھر اور ان کے مال کا وارث بنا دیا اور ایسی زمین کا بھی جس پر تم نے قدم نہیں رکھا اور اللہ ہر چیز پر قادر ہے۔
۳۔ عملی سبق: اللہ کی نعمتوں پر شکر کرو؛ اس کی قدرت مانو؛ اس سے ڈرو۔"""
),
3561: (
"اے نبی اپنی بیویوں سے کہہ دیجیے اگر تم دنیا کی زندگی اور اس کی رونق چاہتی ہو تو آؤ میں تمہیں فائدہ دوں اور تمہیں اچھے طریقے سے رخصت کر دوں",
"""۱۔ نبی ﷺ کی ازواج — دنیا بمقابلہ آخرت کا انتخاب؛ طلاق کی پیشکش۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ إِن كُنتُنَّ تُرِدْنَ الْحَيَاۃَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا‘‘ — اے نبی اپنی بیویوں سے کہہ دیجیے اگر تم دنیا کی زندگی اور اس کی رونق چاہتی ہو تو آؤ میں تمہیں فائدہ دوں اور تمہیں اچھے طریقے سے رخصت کر دوں — یعنی اے نبی اپنی بیویوں سے کہہ دیجیے اگر تم دنیا کی زندگی اور اس کی رونق چاہتی ہو تو آؤ میں تمہیں فائدہ دوں اور تمہیں اچھے طریقے سے رخصت کر دوں۔
۳۔ عملی سبق: دنیا اور آخرت میں انتخاب کرو؛ آخرت کو ترجیح دو؛ اللہ سے ڈرو۔"""
),
3562: (
"اور اگر تم اللہ اور اس کے رسول اور آخرت کے گھر کو چاہتی ہو تو بے شک اللہ نے تم میں سے نیکی کرنے والوں کے لیے بڑا اجر تیار کیا ہے",
"""۱۔ ازواجِ مطہرات — اللہ و رسول ﷺ و آخرت کا انتخاب؛ اجرِ عظیم۔
۲۔ ’’وَإِن كُنتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَۃَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنكُنَّ أَجْرًا عَظِيمًا‘‘ — اور اگر تم اللہ اور اس کے رسول اور آخرت کے گھر کو چاہتی ہو تو بے شک اللہ نے تم میں سے نیکی کرنے والوں کے لیے بڑا اجر تیار کیا ہے — یعنی اور اگر تم اللہ اور اس کے رسول اور آخرت کے گھر کو چاہتی ہو تو بے شک اللہ نے تم میں سے نیکی کرنے والوں کے لیے بڑا اجر تیار کیا ہے۔
۳۔ عملی سبق: اللہ اور اس کے رسول ﷺ کو ترجیح دو؛ نیکی کرو؛ اجر مانگو۔"""
),
3563: (
"اے نبی کی بیویو تم میں سے جو کوئی واضح بےحیائی کرے گی اسے دوہرا عذاب دیا جائے گا — اور یہ اللہ پر آسان ہے",
"""۱۔ ازواجِ مطہرات — بے حیائی کی سخت سزا؛ دوہرا عذاب؛ اللہ کی قدرت۔
۲۔ ’’يَا نِسَاءَ النَّبِيِّ مَن يَأْتِ مِنكُنَّ بِفَاحِشَۃٍ مُّبَيِّنَۃٍ يُضَاعَفْ لَهَا الْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى اللَّهِ يَسِيرًا‘‘ — اے نبی کی بیویو تم میں سے جو کوئی واضح بےحیائی کرے گی اسے دوہرا عذاب دیا جائے گا — اور یہ اللہ پر آسان ہے — یعنی اے نبی کی بیویو تم میں سے جو کوئی واضح بےحیائی کرے گی اسے دوہرا عذاب دیا جائے گا اور یہ اللہ پر آسان ہے۔
۳۔ عملی سبق: بےحیائی سے بچو؛ پاک رہو؛ اللہ سے ڈرو۔"""
),
}
